pub(super) fn analysis__historical_regression__metric_regressed(
    mut metric: Value,
    mut baseline_metrics: Value,
) -> Result<Value> {
    let mut baseline: Value;
    let mut baseline_value: Value;
    let mut current: Value;
    let mut direction: Value;
    baseline = get(
        &baseline_metrics,
        &indexed(&metric, &json!("metric_type"))?,
        Value::Null,
    );
    if equal(&baseline, &Value::Null) {
        return Ok({
            let first = json!(contains(
                &unique(vec![json!("up"), json!("down")]),
                &indexed(&metric, &json!("trend_direction"))?
            ));
            if !truth(&first) {
                first
            } else {
                json!(contains(
                    &catalog("analysis_historical_regression__REGRESSION_DIRECTIONS"),
                    &indexed(&metric, &json!("metric_type"))?
                ))
            }
        });
    }
    let Ok(parsed) = number(&baseline) else {
        return Ok(json!(false));
    };
    baseline_value = json!(parsed);
    current = indexed(&metric, &json!("value"))?;
    direction = get(
        &catalog("analysis_historical_regression__REGRESSION_DIRECTIONS"),
        &indexed(&metric, &json!("metric_type"))?,
        Value::Null,
    );
    if equal(&direction, &json!("up_is_bad")) {
        return Ok(json!(compare(&current, &baseline_value).is_gt()));
    }
    if equal(&direction, &json!("down_is_bad")) {
        return Ok(json!(compare(&current, &baseline_value).is_lt()));
    }
    return Ok(json!(false));
}

