pub(super) fn analysis__historical_regression__normalize_regression_config(
    mut raw_config: Value,
) -> Result<Value> {
    let mut baseline_window: Value;
    let mut config: Value;
    let mut recurrences: Value;
    let mut time_series: Value;
    let mut trend_metrics: Value;
    config = builtin(
        "dict",
        &[{
            let first = raw_config.clone();
            if truth(&first) { first } else { json!({}) }
        }],
    )?;
    baseline_window = analysis__historical_regression__normalize_baseline_window(get(
        &config,
        &json!("baseline_window"),
        json!({}),
    ))?;
    trend_metrics = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("trend_metrics"), Value::Array(vec![])))? {
            let mut m = current;
            if !(m.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__historical_regression__normalize_trend_metric(
                m.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    recurrences = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("recurrences"), Value::Array(vec![])))? {
            let mut r = current;
            if !(r.clone().is_object()) {
                continue;
            }
            collected_values.push(analysis__historical_regression__normalize_recurrence(
                r.clone(),
            )?);
        }
        Value::Array(collected_values)
    };
    time_series = {
        let mut collected_values = Vec::new();
        for current in sequence(&get(&config, &json!("time_series"), Value::Array(vec![])))? {
            let mut p = current;
            if !(p.clone().is_object()) {
                continue;
            }
            collected_values
                .push(analysis__historical_regression__normalize_time_series_point(p.clone())?);
        }
        Value::Array(collected_values)
    };
    return Ok(Value::Object(
        [
            ("baseline_window".into(), baseline_window.clone()),
            ("trend_metrics".into(), trend_metrics.clone()),
            ("recurrences".into(), recurrences.clone()),
            ("time_series".into(), time_series.clone()),
            (
                "parser_regression_detected".into(),
                json!(truth(&get(
                    &config,
                    &json!("parser_regression_detected"),
                    json!(false)
                ))),
            ),
            (
                "recurring_failure_pattern".into(),
                json!(truth(&get(
                    &config,
                    &json!("recurring_failure_pattern"),
                    json!(false)
                ))),
            ),
            (
                "risk_debt_burn_rate".into(),
                json!(number(&{
                    let first = get(&config, &json!("risk_debt_burn_rate"), json!(0.0));
                    if truth(&first) { first } else { json!(0.0) }
                })?),
            ),
            (
                "analysis_scope".into(),
                json!(values::text(&{
                    let first = get(&config, &json!("analysis_scope"), json!(""));
                    if truth(&first) { first } else { json!("") }
                })),
            ),
            ("input_refs".into(), {
                let mut collected_values = Vec::new();
                for current in sequence(&get(&config, &json!("input_refs"), Value::Array(vec![])))?
                {
                    let mut r#ref = current;
                    if !(truth(&json!(values::text(&r#ref)))) {
                        continue;
                    }
                    collected_values.push(json!(values::text(&r#ref)));
                }
                Value::Array(collected_values)
            }),
            (
                "confidence".into(),
                json!(number(&{
                    let first = get(&config, &json!("confidence"), json!(0.0));
                    if truth(&first) { first } else { json!(0.0) }
                })?),
            ),
            (
                "limits".into(),
                analysis__historical_regression__normalize_limits(get(
                    &config,
                    &json!("limits"),
                    json!({}),
                ))?,
            ),
        ]
        .into_iter()
        .collect(),
    ));
}

